// Package: AWSSDK.SQS
using Amazon.SQS;
using Amazon.SQS.Model;

var sqsClient = new AmazonSQSClient(RegionEndpoint.USEast1);
var queueUrl = "https://sqs.us-east-1.amazonaws.com/123456789012/aspnet-orders-queue";

var sendRequest = new SendMessageRequest
{
    QueueUrl = queueUrl,
    MessageBody = "OrderId=1001;CustomerId=42;Total=59.99",
    DelaySeconds = 0
};

var response = await sqsClient.SendMessageAsync(sendRequest);
Console.WriteLine($"Message sent. MD5: {response.MD5OfMessageBody}");

using Amazon.SQS;
using Amazon.SQS.Model;

var receiveRequest = new ReceiveMessageRequest
{
    QueueUrl = queueUrl,
    MaxNumberOfMessages = 10,
    WaitTimeSeconds = 5
};

var receiveResponse = await sqsClient.ReceiveMessageAsync(receiveRequest);

foreach (var message in receiveResponse.Messages)
{
    try
    {
        Console.WriteLine($"Processing: {message.Body}");
        // TODO: process order

        await sqsClient.DeleteMessageAsync(new DeleteMessageRequest
        {
            QueueUrl = queueUrl,
            ReceiptHandle = message.ReceiptHandle
        });
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Failed to process message: {ex.Message}");
    }
}
